--
-- Name: auto_update_dashboard_fee(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_update_dashboard_fee() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- যখনই পেমেন্ট টেবিলে নতুন টাকা জমা হবে, এটি fee_records আপডেট করবে
    UPDATE fee_records
    SET 
        amount_paid = COALESCE(amount_paid, 0) + NEW.amount,
        updated_at = CURRENT_TIMESTAMP,
        status = CASE 
            WHEN (COALESCE(amount_paid, 0) + NEW.amount) >= tuition_fee THEN 'Paid' 
            ELSE 'Partial' 
        END
    WHERE student_id = NEW.student_id;
    
    RETURN NEW;
END;
$$;


--
-- Name: calc_fuel_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_fuel_cost() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.total_cost := NEW.fuel_quantity * NEW.fuel_price;
    RETURN NEW;
END;
$$;


--
-- Name: get_student_transport_fee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_student_transport_fee(student_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    actual_fee NUMERIC;
BEGIN
    -- স্টুডেন্টের নির্দিষ্ট স্টপেজ থেকে ভাড়া খুঁজে বের করা
    SELECT rs.monthly_fee INTO actual_fee
    FROM transport_subscriptions ts
    JOIN route_stops rs ON ts.stop_id = rs.id
    WHERE ts.student_user_id = student_uuid AND ts.status = 'active';

    -- যদি ট্রান্সপোর্ট না থাকে তবে ০ ফেরত দেবে
    RETURN COALESCE(actual_fee, 0.00);
END;
$$;


--
-- Name: sync_student_name_to_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_student_name_to_users() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- users টেবিলের full_name আপডেট করা হচ্ছে
    UPDATE users 
    SET full_name = TRIM(CONCAT(NEW.first_name, ' ', NEW.middle_name, ' ', NEW.last_name))
    WHERE id = NEW.user_id;
    
    RETURN NEW;
END;
$$;


