--
-- Name: session_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.session_overview AS
 SELECT s.academic_session_id,
    s.session_name,
    count(DISTINCT st.student_id) AS total_students,
    COALESCE(sum(fr.tuition_fee), (0)::numeric) AS total_expected,
    COALESCE(sum(fr.amount_paid), (0)::numeric) AS total_collected,
    COALESCE(sum((fr.tuition_fee - fr.amount_paid)), (0)::numeric) AS total_pending
   FROM ((public.academic_sessions s
     LEFT JOIN public.students st ON ((s.academic_session_id = st.academic_session_id)))
     LEFT JOIN public.fee_records fr ON ((st.student_id = fr.student_id)))
  WHERE (s.is_active = true)
  GROUP BY s.academic_session_id, s.session_name;


