--
-- Name: view_finance_defaulters; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_finance_defaulters AS
 SELECT s.student_id,
    u.username AS student_name,
    u.email,
    u.phone_number AS parent_phone,
    s.roll_number,
    s.last_finance_reminder_sent,
    c.course_name,
    count(i.id) AS pending_invoices,
    sum((i.total_amount - i.paid_amount)) AS total_due
   FROM (((public.students s
     JOIN public.users u ON ((s.user_id = u.id)))
     LEFT JOIN public.courses c ON ((s.course_id = c.id)))
     JOIN public.student_invoices i ON ((s.student_id = i.student_id)))
  WHERE (((i.status)::text <> 'Paid'::text) AND ((i.status)::text <> 'Waived'::text))
  GROUP BY s.student_id, u.username, u.email, u.phone_number, s.roll_number, s.last_finance_reminder_sent, c.course_name
 HAVING (sum((i.total_amount - i.paid_amount)) > (0)::numeric);


--
-- Name: view_transport_financial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_transport_financial_summary AS
 SELECT r.route_name,
    v.vehicle_no,
    count(ts.student_user_id) AS total_students,
    sum(rs.monthly_fee) AS total_monthly_revenue,
    v.seating_capacity,
    (v.seating_capacity - count(ts.student_user_id)) AS available_seats
   FROM (((public.transport_routes r
     JOIN public.transport_vehicles v ON ((r.id IN ( SELECT transport_subscriptions.route_id
           FROM public.transport_subscriptions
          WHERE (transport_subscriptions.vehicle_id = v.id)))))
     LEFT JOIN public.transport_subscriptions ts ON (((r.id = ts.route_id) AND ((ts.status)::text = 'active'::text))))
     LEFT JOIN public.route_stops rs ON ((ts.stop_id = rs.id)))
  GROUP BY r.route_name, v.vehicle_no, v.seating_capacity;


--
-- Name: view_vehicle_compliance_alerts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_vehicle_compliance_alerts AS
 SELECT vehicle_no,
    model,
    insurance_expiry,
    fitness_expiry,
        CASE
            WHEN (insurance_expiry < CURRENT_DATE) THEN 'Insurance Expired'::text
            WHEN (insurance_expiry < (CURRENT_DATE + '15 days'::interval)) THEN 'Insurance Expiring Soon'::text
            ELSE 'Active'::text
        END AS insurance_status,
        CASE
            WHEN (fitness_expiry < CURRENT_DATE) THEN 'Fitness Expired'::text
            WHEN (fitness_expiry < (CURRENT_DATE + '15 days'::interval)) THEN 'Fitness Expiring Soon'::text
            ELSE 'Active'::text
        END AS fitness_status
   FROM public.transport_vehicles;


